/* Thành phần giao diện và bộ dựng trang dùng chung. */
(function () {
  const roleNames = { seeker: 'Người tìm nhà', agent: 'Môi giới', moderator: 'Kiểm duyệt viên', admin: 'Quản trị viên' };
  const pageTitles = {
    index: 'Khám phá nhà theo nhu cầu sống', login: 'Đăng nhập', register: 'Tạo tài khoản', 'forgot-password': 'Khôi phục mật khẩu',
    profile: 'Hồ sơ cá nhân', notifications: 'Thông báo', help: 'Trợ giúp', '403': 'Không có quyền truy cập', '404': 'Không tìm thấy trang',
    'seeker-property-search': 'Tìm nhà phù hợp', 'seeker-property-detail': 'Chi tiết nhà', 'seeker-property-compare': 'So sánh nhà', 'seeker-home-brief': 'Brief nhu cầu của tôi', 'seeker-my-space': 'Của tôi',
    'agent-dashboard': 'Tổng quan môi giới', 'agent-listing-management': 'Quản lý tin đăng', 'agent-listing-upload': 'Đăng tin mới', 'agent-listing-edit': 'Sửa tin đăng', 'agent-lead-management': 'Khách hàng tiềm năng', 'agent-viewing-schedule': 'Lịch xem nhà',
    'moderator-listing-review': 'Kiểm duyệt tin đăng', 'moderator-report-center': 'Trung tâm báo cáo', 'moderator-data-quality': 'Chất lượng dữ liệu',
    'admin-category-management': 'Danh mục hệ thống', 'admin-user-management': 'Quản lý tài khoản', 'admin-platform-dashboard': 'Bảng điều khiển nền tảng'
  };
  const menuByRole = {
    agent: [['Tổng quan', 'agent-dashboard'], ['Tin đăng', 'agent-listing-management'], ['Khách hàng tiềm năng', 'agent-lead-management'], ['Lịch xem', 'agent-viewing-schedule']],
    moderator: [['Duyệt tin', 'moderator-listing-review'], ['Báo cáo', 'moderator-report-center'], ['Chất lượng dữ liệu', 'moderator-data-quality']],
    admin: [['Bảng điều khiển', 'admin-platform-dashboard'], ['Danh mục', 'admin-category-management'], ['Tài khoản', 'admin-user-management']]
  };
  const protectedPages = {
    'seeker-property-search': 'seeker', 'seeker-property-detail': 'seeker', 'seeker-property-compare': 'seeker', 'seeker-home-brief': 'seeker', 'seeker-my-space': 'seeker',
    'agent-dashboard': 'agent', 'agent-listing-management': 'agent', 'agent-listing-upload': 'agent', 'agent-listing-edit': 'agent', 'agent-lead-management': 'agent', 'agent-viewing-schedule': 'agent',
    'moderator-listing-review': 'moderator', 'moderator-report-center': 'moderator', 'moderator-data-quality': 'moderator',
    'admin-category-management': 'admin', 'admin-user-management': 'admin', 'admin-platform-dashboard': 'admin'
  };
  const $ = (selector, root = document) => root.querySelector(selector);
  const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const money = (value) => `${Number(value).toLocaleString('vi-VN')} triệu/tháng`;
  const go = (page, query = '') => { window.location.href = `${HomeFitAuth.pageUrl(`${page}.html`)}${query}`; };
  const rows = (table) => HomeFitStorage.getAll(table);
  const prop = (id) => HomeFitStorage.getById('properties', id);

  function renderNavbar(container) {
    const user = HomeFitAuth.getCurrentUser();
    const unread = user ? rows('notifications').filter((item) => item.userId === user.id && !item.read).length : 0;
    const navLinks = user?.role === 'seeker'
      ? [['Trang chủ', 'index'], ['Tìm nhà', 'seeker-property-search'], ['So sánh', 'seeker-property-compare'], ['Brief của tôi', 'seeker-home-brief'], ['Của tôi', 'seeker-my-space'], ['Trợ giúp', 'help']]
      : [['Trang chủ', 'index'], ['Trợ giúp', 'help']];
    container.innerHTML = `<nav class="navbar navbar-expand-lg"><div class="container"><a class="navbar-brand fw-bold" href="${HomeFitAuth.pageUrl('index.html')}">HomeFit <span class="hf-accent">AI</span></a><button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#hfNav"><span class="navbar-toggler-icon"></span></button><div class="collapse navbar-collapse" id="hfNav"><ul class="navbar-nav me-auto">${navLinks.map(([label, page]) => `<li class="nav-item"><a class="nav-link" href="${HomeFitAuth.pageUrl(`${page}.html`)}">${label}</a></li>`).join('')}</ul><div class="d-flex align-items-center gap-2">${user ? `<a class="btn btn-light position-relative" href="${HomeFitAuth.pageUrl('notifications.html')}" aria-label="Thông báo">🔔 <span class="badge rounded-pill text-bg-success">${unread}</span></a><div class="dropdown"><button class="btn btn-outline-primary dropdown-toggle" data-bs-toggle="dropdown">${esc(user.name)}</button><ul class="dropdown-menu dropdown-menu-end"><li><a class="dropdown-item" href="${HomeFitAuth.pageUrl('profile.html')}">Hồ sơ</a></li>${user.role === 'seeker' ? `<li><a class="dropdown-item" href="${HomeFitAuth.pageUrl('seeker-my-space.html')}">Của tôi</a></li>` : ''}<li><a class="dropdown-item" href="${HomeFitAuth.pageUrl('notifications.html')}">Thông báo</a></li><li><button class="dropdown-item" data-action="logout">Đăng xuất</button></li></ul></div>` : `<a class="btn btn-outline-primary" href="${HomeFitAuth.pageUrl('login.html')}">Đăng nhập</a><a class="btn btn-primary" href="${HomeFitAuth.pageUrl('register.html')}">Đăng ký</a>`}</div></div></div></nav>`;
  }

  function renderSidebar(user, page) {
    const links = menuByRole[user.role] || [];
    const items = `${links.map(([label, key]) => `<a class="nav-link ${page === key ? 'active' : ''}" href="${HomeFitAuth.pageUrl(`${key}.html`)}">${label}</a>`).join('')}<a class="nav-link" href="${HomeFitAuth.pageUrl('notifications.html')}">Thông báo</a><a class="nav-link" href="${HomeFitAuth.pageUrl('profile.html')}">Hồ sơ</a>`;
    return `<button class="btn btn-outline-primary m-2 d-md-none" type="button" data-bs-toggle="offcanvas" data-bs-target="#hfRoleMenu">☰ Mở menu</button><div class="offcanvas offcanvas-start d-md-none" tabindex="-1" id="hfRoleMenu"><div class="offcanvas-header"><h2 class="h5">${roleNames[user.role]}</h2><button class="btn-close" data-bs-dismiss="offcanvas"></button></div><div class="offcanvas-body"><nav class="nav flex-column gap-1">${items}</nav></div></div><aside class="hf-sidebar p-3 d-none d-md-block"><div class="small text-secondary mb-2">${roleNames[user.role]}</div><nav class="nav flex-column gap-1">${items}</nav></aside>`;
  }

  function renderFooter(container) {
    if (!container) return;
    container.innerHTML = `<footer class="site-footer border-top mt-5"><div class="container py-4"><div class="row g-3 align-items-center"><div class="col-lg-6"><a class="navbar-brand fw-bold" href="${HomeFitAuth.pageUrl('index.html')}">HomeFit <span class="hf-accent">AI</span></a><p class="small text-secondary mb-0">Tìm nơi ở phù hợp với cuộc sống của bạn.</p></div><div class="col-lg-4 small"><a href="mailto:hello@homefit.vn">hello@homefit.vn</a><span class="mx-2">·</span><a href="tel:19001234">1900 1234</a></div><div class="col-lg-2 text-lg-end"><a class="small" href="${HomeFitAuth.pageUrl('login.html?audience=agent')}">Dành cho môi giới</a></div><div class="col-12 small text-secondary border-top pt-3">© 2026 HomeFit. Bảo lưu mọi quyền.</div></div></div></footer>`;
  }

  function toast(message, kind = 'success') {
    const host = $('#hfToastHost') || (() => { const node = document.createElement('div'); node.id = 'hfToastHost'; node.className = 'toast-container position-fixed bottom-0 end-0 p-3'; document.body.append(node); return node; })();
    const node = document.createElement('div');
    node.className = `toast text-bg-${kind} border-0`;
    node.innerHTML = `<div class="d-flex"><div class="toast-body">${esc(message)}</div><button class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast" aria-label="Đóng"></button></div>`;
    host.append(node);
    const instance = bootstrap.Toast.getOrCreateInstance(node, { delay: 3000 });
    node.addEventListener('hidden.bs.toast', () => node.remove(), { once: true });
    instance.show();
  }

  function confirmDialog(message, title = 'Xác nhận') {
    return new Promise((resolve) => {
      const node = document.createElement('div');
      node.className = 'modal fade'; node.tabIndex = -1;
      node.innerHTML = `<div class="modal-dialog modal-dialog-centered"><div class="modal-content"><div class="modal-header"><h2 class="modal-title fs-5">${esc(title)}</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">${esc(message)}</div><div class="modal-footer"><button class="btn btn-outline-secondary" data-cancel>Hủy</button><button class="btn btn-primary" data-confirm>Tiếp tục</button></div></div></div>`;
      document.body.append(node); const modal = new bootstrap.Modal(node); let result = false;
      $('[data-confirm]', node).addEventListener('click', () => { result = true; modal.hide(); });
      $('[data-cancel]', node).addEventListener('click', () => modal.hide());
      node.addEventListener('hidden.bs.modal', () => { node.remove(); resolve(result); }, { once: true }); modal.show();
    });
  }

  function showState(container, state, options = {}) {
    const messages = { empty: '<div class="hf-state"><h3 class="h5">Chưa có dữ liệu</h3><p>Hãy thêm mục mới hoặc thay đổi điều kiện lọc.</p></div>', error: `<div class="alert alert-danger">${esc(options.message || 'Không tải được dữ liệu.')} <button class="btn btn-sm btn-outline-danger" data-retry>Thử lại</button></div>`, loading: '<div class="hf-skeleton hf-state" aria-label="Đang tải"></div>' };
    if (state === 'content') { container.innerHTML = options.content || ''; return; }
    container.innerHTML = messages[state] || messages.error;
    if (state === 'error' && options.onRetry) $('[data-retry]', container).addEventListener('click', options.onRetry);
  }

  function formatDate(value, withTime = false) {
    const date = new Date(value); if (Number.isNaN(date.getTime())) return '';
    return new Intl.DateTimeFormat('vi-VN', withTime ? { dateStyle: 'medium', timeStyle: 'short' } : { dateStyle: 'medium' }).format(date);
  }

  function formatRelativeDate(value) {
    const date = new Date(value); if (Number.isNaN(date.getTime())) return '';
    const today = new Date(); today.setHours(0,0,0,0);
    const target = new Date(date); target.setHours(0,0,0,0);
    const days = Math.round((target - today) / 86400000);
    const dayLabel = days === 0 ? 'Hôm nay' : days === 1 ? 'Ngày mai' : days === -1 ? 'Hôm qua' : formatDate(date);
    return `${dayLabel} ${new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit'}).format(date)}`;
  }

  function tagLines(property, brief) {
    const checks = [['Gần trường', property.schoolDistance <= 500], ['Yên tĩnh', ['Cao', 'Rất cao'].includes(property.quietness)], ['Có chỗ làm việc', property.workspace], ['Trong ngân sách', property.price <= brief.budget], ['Đủ phòng ngủ', property.bedrooms >= brief.bedrooms]];
    return checks.slice(0, 3).map(([label, matched]) => ({ label, matched }));
  }

  function propertyCard(item, score) {
    const brief = rows('briefs').find((row) => row.id === 'brief_1') || { budget: 14, bedrooms: 2 };
    const tags = tagLines(item, brief).map((tag) => `<span class="${tag.matched ? 'hf-match-yes' : 'hf-match-no'}">${tag.matched ? '✓' : '✗'} ${tag.label}</span>`).join('<br>');
    const imageUrl = item.image || `${HomeFitAuth.pageUrl('..')}/assets/img/property-placeholder.svg`;
    return `<article class="card h-100 property-card"><img src="${esc(imageUrl)}" class="card-img-top" alt="Căn nhà ${esc(item.name)}"><div class="card-body d-flex flex-column"><div class="d-flex justify-content-between gap-2"><h3 class="h5">${esc(item.name)}</h3>${score ? `<span class="hf-score">${score}</span>` : ''}</div><p class="text-secondary mb-2">${esc(item.district)} · ${item.bedrooms} PN · ${item.area} m²</p><p class="fw-semibold">${money(item.price)}</p><div class="small mb-3">${tags}</div><div class="mt-auto d-flex gap-2"><a class="btn btn-primary btn-sm" href="${HomeFitAuth.pageUrl(`seeker-property-detail.html?id=${encodeURIComponent(item.id)}`)}">Xem chi tiết</a><button class="btn btn-outline-primary btn-sm" data-action="save-property" data-id="${item.id}">♡ Lưu</button></div></div></article>`;
  }

  function propertyGrid(list, scored = false) {
    return `<div class="row g-3">${list.map((item) => `<div class="col-sm-6 col-xl-4">${propertyCard(item, scored ? HomeFitAI.matchScore(rows('briefs')[0], item) : 0)}</div>`).join('')}</div>`;
  }

  function dataTable(headers, list, renderRow) {
    if (!list.length) return '<div class="alert alert-light border">Chưa có dữ liệu phù hợp.</div>';
    const mobileRows = list.map((item) => {
      let cellIndex = 0;
      const rowHtml = renderRow(item).replace(/<td(?=[ >])/g, () => `<td data-label="${esc(headers[cellIndex++] || '')}"`);
      return rowHtml;
    }).join('');
    return `<div class="table-responsive"><table class="table align-middle hf-mobile-table"><thead class="table-light d-none d-md-table-header-group"><tr>${headers.map((x) => `<th>${x}</th>`).join('')}</tr></thead><tbody>${mobileRows}</tbody></table></div>`;
  }

  function pageBody(page) {
    const user = HomeFitAuth.getCurrentUser(); const properties = rows('properties'); const briefs = rows('briefs');
    if (page === 'index') return `
      <section class="hero rounded-4 p-4 p-lg-5 mb-5">
        <div class="row align-items-center g-4"><div class="col-lg-7">
          <span class="badge text-bg-warning mb-3">HomeFit · Thuê nhà hợp với nhịp sống</span>
          <h1 class="display-5 fw-bold">Tìm nơi bạn muốn<br>trở về mỗi ngày</h1>
          <p class="lead">Chia sẻ điều bạn cần ở một ngôi nhà. Khám phá lựa chọn phù hợp với ngân sách và cuộc sống của bạn.</p>
          <form data-form="quick-search" class="input-group input-group-lg"><input name="q" class="form-control" placeholder="gần trường, yên tĩnh, dưới 14 triệu ở Cầu Giấy"><button class="btn btn-primary">Tìm nhà</button></form>
        </div><div class="col-lg-5"><img class="img-fluid rounded-4 shadow" src="${esc(prop('P01').image)}" alt="Không gian nhà sáng và thoáng"></div></div>
      </section>
      <section class="mb-5"><div class="d-flex justify-content-between align-items-end mb-3"><div><p class="text-secondary mb-1">Lựa chọn đáng chú ý</p><h2 class="h3 mb-0">Nhà đang được quan tâm</h2></div><a href="${HomeFitAuth.pageUrl('seeker-property-search.html')}" class="btn btn-outline-primary">Xem tất cả nhà</a></div><div class="row g-3">${['P01','P02','P03'].map((id)=>`<div class="col-md-6 col-xl-4">${propertyCard(prop(id),HomeFitAI.matchScore(rows('briefs')[0],prop(id)))}</div>`).join('')}</div></section>
      <section class="mb-5"><div class="text-center mb-4"><p class="text-secondary mb-1">Bắt đầu thật dễ dàng</p><h2 class="h3">Ba bước để tìm đúng nơi ở</h2></div><div class="row g-3">${[['01','Chia sẻ nhu cầu','Khu vực, ngân sách và những điều khiến bạn thấy thoải mái.'],['02','Khám phá lựa chọn','Xem các căn nhà phù hợp và hiểu rõ điểm mạnh của từng nơi.'],['03','Sắp xếp buổi xem','Lưu nhà yêu thích, so sánh và hẹn lịch trực tiếp.']].map(([n,t,d])=>`<div class="col-md-4"><article class="card h-100"><div class="card-body"><span class="hf-score mb-3">${n}</span><h3 class="h5">${t}</h3><p class="mb-0">${d}</p></div></article></div>`).join('')}</div></section>
      <section class="rounded-4 p-4 p-lg-5 mb-5 bg-white"><div class="row align-items-center g-4"><div class="col-lg-5"><h2 class="h3">Một ngôi nhà tốt bắt đầu từ điều bạn cần</h2><p class="mb-0">HomeFit giúp bạn cân nhắc vị trí, ngân sách và thói quen sinh hoạt trong cùng một hành trình tìm nhà.</p></div><div class="col-lg-7"><div class="row g-3"><div class="col-sm-6"><h3 class="h6">Thông tin rõ ràng</h3><p class="small">Giá thuê theo tháng, diện tích và tiện ích được trình bày dễ so sánh.</p></div><div class="col-sm-6"><h3 class="h6">Gợi ý có lý do</h3><p class="small">Biết lựa chọn phù hợp ở điểm nào để tự tin quyết định.</p></div><div class="col-sm-6"><h3 class="h6">Theo nhu cầu sống</h3><p class="small">Tìm theo nhịp sống của bạn, từ gần trường đến không gian làm việc.</p></div><div class="col-sm-6"><h3 class="h6">Dễ kết nối</h3><p class="small">Đặt lịch xem nhà và trao đổi với người đăng tin ngay trên HomeFit.</p></div></div></div></div></section>
      <section class="mb-5"><h2 class="h3 mb-3">Câu hỏi thường gặp</h2><div class="accordion" id="homeFaq"><div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button" data-bs-toggle="collapse" data-bs-target="#homeFaqOne">Tôi có thể lọc nhà theo ngân sách không?</button></h3><div id="homeFaqOne" class="accordion-collapse collapse show" data-bs-parent="#homeFaq"><div class="accordion-body">Có. Bạn có thể đặt mức thuê tối đa theo tháng và kết hợp thêm khu vực, diện tích hoặc nhu cầu sống.</div></div></div><div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button collapsed" data-bs-toggle="collapse" data-bs-target="#homeFaqTwo">Làm sao để xem nhiều căn nhà cùng lúc?</button></h3><div id="homeFaqTwo" class="accordion-collapse collapse" data-bs-parent="#homeFaq"><div class="accordion-body">Thêm các căn nhà vào danh sách so sánh để xem giá, diện tích và tiện ích cạnh nhau.</div></div></div></div></section>`;
    if (page === 'login') return `<div class="auth-card card mx-auto"><div class="card-body p-4"><h1 class="h3 mb-3">Đăng nhập</h1><p class="text-secondary">Chào mừng bạn trở lại HomeFit.</p><form data-form="login"><label class="form-label">Email</label><input class="form-control mb-3" name="email" type="email" autocomplete="username" required><label class="form-label">Mật khẩu</label><input class="form-control mb-3" name="password" type="password" autocomplete="current-password" required><div class="text-danger small mb-2" data-error></div><div class="d-flex justify-content-between mb-3"><a href="${HomeFitAuth.pageUrl('forgot-password.html')}">Quên mật khẩu?</a><a href="${HomeFitAuth.pageUrl('register.html')}">Đăng ký</a></div><button class="btn btn-primary w-100">Đăng nhập</button></form></div></div>`;
    if (page === 'register') return `<div class="auth-card card mx-auto"><div class="card-body p-4"><h1 class="h3">Tạo tài khoản người tìm nhà</h1><form data-form="register"><label class="form-label">Họ và tên</label><input class="form-control mb-3" name="name" required><label class="form-label">Email</label><input class="form-control mb-3" name="email" type="email" required><label class="form-label">Mật khẩu (ít nhất 6 ký tự)</label><input class="form-control mb-3" name="password" type="password" minlength="6" required><label class="form-label">Nhập lại mật khẩu</label><input class="form-control mb-3" name="confirm" type="password" required><button class="btn btn-primary">Đăng ký</button></form></div></div>`;
    if (page === 'forgot-password') return `<div class="auth-card card mx-auto"><div class="card-body p-4"><h1 class="h3">Khôi phục mật khẩu</h1><form data-form="forgot"><label class="form-label">Email tài khoản</label><input name="email" type="email" class="form-control mb-3" required><div data-reset-fields hidden><label class="form-label">Mật khẩu mới</label><input name="password" type="password" minlength="6" class="form-control mb-3"><label class="form-label">Nhập lại mật khẩu</label><input name="confirm" type="password" class="form-control mb-3"></div><button class="btn btn-primary">Tiếp tục</button></form></div></div>`;
    if (page === '403' || page === '404') { const homePage=user?.role==='agent'?'agent-dashboard.html':user?.role==='moderator'?'moderator-listing-review.html':user?.role==='admin'?'admin-platform-dashboard.html':user?'seeker-property-search.html':'index.html'; return `<div class="text-center py-5"><div class="display-1 fw-bold hf-accent">${page}</div><h1>${page === '403' ? 'Bạn chưa có quyền xem trang này' : 'Trang bạn tìm không tồn tại'}</h1><a class="btn btn-primary mt-3" href="${HomeFitAuth.pageUrl(homePage)}">Về trang chủ</a></div>`; }
    if (page === 'seeker-property-search') return `<div class="row g-4"><aside class="col-lg-3"><div class="card"><div class="card-body"><h2 class="h5">Bộ lọc</h2><form data-form="search"><label class="form-label">Từ khóa</label><input class="form-control mb-3" name="q" value="${esc(new URLSearchParams(location.search).get('q') || '')}"><label class="form-label">Ngân sách tối đa (triệu/tháng)</label><input class="form-control mb-3" name="budget" type="number" value="14"><label class="form-label">Quận</label><select class="form-select mb-3" name="district"><option value="">Tất cả khu vực</option>${[...new Set(properties.map((p) => p.district))].map((d) => `<option>${esc(d)}</option>`).join('')}</select><button class="btn btn-primary w-100">Áp dụng</button></form></div></div></aside><div class="col-lg-9"><div class="alert alert-success">Đang dùng Brief #1 · Cầu Giấy · ≤ 14 triệu · 2PN <button class="btn-close float-end" data-action="remove-brief"></button></div><div class="d-flex justify-content-between mb-3"><h1 class="h3">Nhà đã duyệt</h1><button class="btn btn-outline-primary" data-action="compare-selected">So sánh nhà đã chọn</button></div><div id="property-results">${propertyGrid(properties.filter((p) => p.status === 'Đã duyệt'), true)}</div></div></div>`;
    if (page === 'seeker-property-detail') { const item = prop(new URLSearchParams(location.search).get('id') || 'P01') || prop('P01'); return `<div class="row g-4"><div class="col-lg-7"><img class="img-fluid rounded-4 mb-3" src="${esc(item.image || HomeFitAuth.pageUrl('../assets/img/property-placeholder.svg'))}" alt="Không gian nhà ${esc(item.name)}"><h1>${esc(item.name)}</h1><p>${esc(item.district)} · ${item.bedrooms} phòng ngủ · ${item.area} m²</p><h2 class="h4">${money(item.price)}</h2><p>${esc(item.description)}</p><button class="btn btn-primary" data-action="save-property" data-id="${item.id}">♡ Lưu nhà</button> <button class="btn btn-outline-primary" data-action="add-compare" data-id="${item.id}">Thêm so sánh</button> <button class="btn btn-outline-primary" data-action="book-viewing" data-id="${item.id}">Đặt lịch xem</button> <button class="btn btn-outline-secondary" data-action="send-message" data-id="${item.id}">Gửi tin nhắn</button> <button class="btn btn-outline-danger" data-action="report-property" data-id="${item.id}">Báo cáo tin</button></div><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h5">Tóm tắt AI</h2><p>${esc(HomeFitAI.listingSummary(item).summary)}</p><p class="small text-secondary">Vì sao? Tóm tắt từ dữ liệu tin đăng đã cung cấp. Chấp nhận sẽ ghim tóm tắt vào ghi chú nhà đã lưu.</p><div class="d-flex flex-wrap gap-2">${aiButtons('AI-2 seeker')}</div></div></div></div></div>`; }
    if (page === 'seeker-property-compare') return `<h1 class="h3">So sánh nhà</h1><p>Chọn từ danh sách đã lưu. Điểm so sánh được tính theo tiêu chí đang chọn.</p><div class="d-flex gap-2 mb-3"><select class="form-select w-auto" data-select="compare">${properties.filter((p) => p.status === 'Đã duyệt').map((p) => `<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button class="btn btn-outline-primary" data-action="add-compare-selected">Thêm nhà</button><button class="btn btn-primary" data-action="rank-compare">AI xếp hạng</button></div><div id="compare-results">${compareTable(['P01','P02','P03'])}</div><div data-ranking class="mt-3"></div><section class="card mt-3"><div class="card-body"><h2 class="h5">Comparison Assistant · AI-3</h2><p>Chấp nhận sẽ lưu kết quả xếp hạng và trọng số.</p><div class="d-flex flex-wrap gap-2">${aiButtons('AI-3')}</div></div></section>`;
    if (page === 'seeker-home-brief') return `<div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-body"><h1 class="h3">Tạo brief nhu cầu</h1><form data-form="brief"><div class="row g-3"><div class="col-md-6"><label class="form-label">Khu vực</label><input class="form-control" name="district" value="Cầu Giấy" required></div><div class="col-md-6"><label class="form-label">Địa điểm quan trọng</label><input class="form-control" name="importantPlace" value="Trường đại học"></div><div class="col-md-6"><label class="form-label">Ngân sách (triệu/tháng)</label><input class="form-control" name="budget" type="number" value="14" required></div><div class="col-md-6"><label class="form-label">Phòng ngủ</label><input class="form-control" name="bedrooms" type="number" value="2"></div><div class="col-12"><label class="form-label">Mô tả nhu cầu (tối thiểu 15 ký tự)</label><textarea class="form-control" name="description" minlength="15" required>Cần nhà gần trường, yên tĩnh cho gia đình</textarea></div><div class="col-12 form-check ms-2"><input class="form-check-input" name="shareWithAgent" type="checkbox" checked><label class="form-check-label">Chia sẻ brief với môi giới</label></div><div class="col-12"><button class="btn btn-primary">Tạo brief & chạy AI</button></div></div></form><div data-brief-result class="mt-3"></div></div></div></div><div class="col-lg-5"><h2 class="h5">Brief đã lưu</h2>${briefs.map((b) => `<div class="card mb-2"><div class="card-body"><b>${esc(b.name)}</b> · ${esc(b.district)} · ≤ ${money(b.budget)}<div class="small">${b.bedrooms} phòng ngủ · ${esc(b.status)}</div></div></div>`).join('')}</div></div>`;
    if (page === 'seeker-my-space') return `<h1 class="h3">Của tôi</h1><ul class="nav nav-tabs" role="tablist"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#saved">Đã lưu</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#viewings">Lịch xem</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#myreports">Báo cáo của tôi</button></li></ul><div class="tab-content py-3"><div class="tab-pane fade show active" id="saved">${propertyGrid(rows('savedProperties').filter((s) => s.userId === user?.id).map((s) => prop(s.propertyId)).filter(Boolean))}</div><div class="tab-pane fade" id="viewings">${viewingsTable(rows('viewings').filter((v) => v.customerId === user?.id))}</div><div class="tab-pane fade" id="myreports">${reportsTable(rows('reports').filter((r) => r.reporterId === user?.id))}</div></div>`;
    if (page === 'profile') return profilePage(user);
    if (page === 'notifications') return notificationsPage(user);
    if (page === 'help') return `<h1 class="h3">Trợ giúp HomeFit</h1><div class="accordion" id="faq">${[['Đặt lịch xem nhà','Mở trang chi tiết nhà, chọn Đặt lịch xem, sau đó nhập ngày và giờ phù hợp.'],['So sánh nhà','Chọn tối đa ba tin đã duyệt rồi mở trang So sánh.'],['Báo cáo tin sai','Mở chi tiết tin và chọn Báo cáo tin để gửi lý do.'],['Đăng tin','Môi giới chọn Đăng tin mới và điền các thông tin bắt buộc.'],['Đổi mật khẩu','Dùng liên kết Quên mật khẩu ở màn hình đăng nhập.']].map(([q,a],i)=>`<div class="accordion-item"><h2 class="accordion-header"><button class="accordion-button ${i?'collapsed':''}" data-bs-toggle="collapse" data-bs-target="#faq${i}">${q}</button></h2><div id="faq${i}" class="accordion-collapse collapse ${i?'':'show'}" data-bs-parent="#faq"><div class="accordion-body">${a}</div></div></div>`).join('')}</div><form data-form="help-ai" class="input-group mt-3"><input class="form-control" name="question" placeholder="Hỏi về cách dùng HomeFit"><button class="btn btn-primary">Hỏi trợ giúp</button></form><div data-help-answer class="mt-3"></div>`;
    if (page === 'agent-dashboard') return dashboard('agent');
    if (page === 'agent-listing-management') return `<div class="d-flex justify-content-between"><h1 class="h3">Tin đăng của tôi</h1><a class="btn btn-primary" href="${HomeFitAuth.pageUrl('agent-listing-upload.html')}">+ Đăng tin</a></div>${listingTable(properties)}`;
    if (page === 'agent-listing-upload' || page === 'agent-listing-edit') { const item = page.includes('edit') ? prop(new URLSearchParams(location.search).get('id') || 'P01') : null; return listingForm(item); }
    if (page === 'agent-lead-management') return `<div class="d-flex justify-content-between"><h1 class="h3">Khách hàng tiềm năng</h1><button class="btn btn-primary" data-action="new-lead">Thêm khách hàng</button></div>${leadTable(rows('leads'))}<div class="offcanvas offcanvas-end" tabindex="-1" id="leadDrawer"><div class="offcanvas-header"><h2 class="h5">Chi tiết khách hàng</h2><button class="btn-close" data-bs-dismiss="offcanvas"></button></div><div class="offcanvas-body" data-lead-detail>Chọn một khách hàng để xem thông tin.</div></div>`;
    if (page === 'agent-viewing-schedule') return `<h1 class="h3">Lịch xem nhà</h1><form data-form="viewing" class="card card-body mb-3 row g-3"><div class="col-md-4"><label class="form-label">Nhà</label><select class="form-select" name="propertyId">${properties.map((p)=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></div><div class="col-md-4"><label class="form-label">Khách</label><select class="form-select" name="leadId">${rows('leads').map((l)=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></div><div class="col-md-2"><label class="form-label">Ngày</label><input class="form-control" type="date" name="date" required></div><div class="col-md-2"><label class="form-label">Giờ</label><input class="form-control" type="time" name="time" min="08:00" max="20:00" required></div><div class="col-12"><button class="btn btn-primary">Tạo lịch xem</button></div></form>${viewingsTable(rows('viewings'))}`;
    if (page === 'moderator-listing-review') return reviewQueue(properties);
    if (page === 'moderator-report-center') return `<div class="d-flex justify-content-between"><h1 class="h3">Trung tâm báo cáo</h1><button class="btn btn-primary" data-action="new-report">Tạo báo cáo</button></div>${reportsTable(rows('reports'))}`;
    if (page === 'moderator-data-quality') return dataQuality(properties);
    if (page === 'admin-category-management') return categoriesPage();
    if (page === 'admin-user-management') return `<div class="d-flex justify-content-between"><h1 class="h3">Quản lý tài khoản</h1><button class="btn btn-primary" data-action="new-user">Thêm tài khoản</button></div>${userTable(rows('users'))}`;
    if (page === 'admin-platform-dashboard') return dashboard('admin');
    return `<div class="alert alert-info">Trang đang được thiết lập.</div>`;
  }

  function aiButtons(name) { return ['Chấp nhận','Sửa','Từ chối','Tạo lại','Lưu'].map((label) => `<button class="btn btn-sm btn-outline-primary" data-action="ai-action" data-ai-name="${name}" data-value="${label}">${label}</button>`).join(''); }
  function compareTable(ids) {
    const list = ids.map(prop).filter(Boolean);
    return `<div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Tiêu chí</th>${list.map((p)=>`<th>${esc(p.name)} <button class="btn btn-sm btn-link" data-action="remove-compare" data-id="${p.id}">Bỏ</button></th>`).join('')}</tr></thead><tbody>${[['Giá', (p)=>money(p.price)],['Diện tích',(p)=>`${p.area} m²`],['Phòng ngủ',(p)=>p.bedrooms],['Cách trường',(p)=>`${p.schoolDistance} m`],['Yên tĩnh',(p)=>p.quietness],['Chỗ làm việc',(p)=>p.workspace?'Có':'Không']].map(([label,get])=>`<tr><th>${label}</th>${list.map((p)=>`<td>${get(p)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  }
  function viewingsTable(list) { return dataTable(['Khách','Nhà','Ngày giờ','Trạng thái'], list, (v)=>`<tr><td>${esc(v.customerName || rows('leads').find((l)=>l.id===v.leadId)?.name || '')}</td><td>${esc(prop(v.propertyId)?.name || v.propertyId)}</td><td>${formatRelativeDate(v.scheduledAt)}</td><td><span class="badge text-bg-secondary">${esc(v.status)}</span></td></tr>`); }
  function reportsTable(list) { return dataTable(['Mã','Tin','Lý do','Trạng thái','Kết luận'], list, (r)=>`<tr><td>${esc(r.id)}</td><td>${esc(prop(r.propertyId)?.name || r.propertyId)}</td><td>${esc(r.reason)}</td><td><span class="badge text-bg-warning">${esc(r.status)}</span></td><td>${esc(r.conclusion || '—')}</td></tr>`); }
  function listingTable(list) { return dataTable(['Mã','Tin đăng','Khu vực','Giá','Trạng thái','Thao tác'], list, (p)=>`<tr><td>${p.id}</td><td>${esc(p.name)}</td><td>${esc(p.district)}</td><td>${money(p.price)}</td><td>${esc(p.status)}</td><td><a class="btn btn-sm btn-outline-primary" href="${HomeFitAuth.pageUrl(`agent-listing-edit.html?id=${p.id}`)}">Sửa</a> <button class="btn btn-sm btn-outline-danger" data-action="archive-property" data-id="${p.id}">Lưu trữ</button></td></tr>`); }
  function leadTable(list) { return dataTable(['Khách hàng','Nguồn','Điểm AI','Tin quan tâm','Trạng thái'],list,(l)=>`<tr data-action="open-lead" data-id="${l.id}" role="button"><td>${esc(l.name)}</td><td>${esc(l.source)}</td><td><span class="hf-score">${l.score}</span></td><td>${esc(prop(l.propertyId)?.name || '')}</td><td>${esc(l.status)}</td></tr>`); }
  function userTable(list) { return dataTable(['Tên','Email','Vai trò','Trạng thái','Thao tác'],list,(u)=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${roleNames[u.role]}</td><td>${esc(u.status)}</td><td><button class="btn btn-sm btn-outline-primary" data-action="toggle-user" data-id="${u.id}">${u.status==='Khóa'?'Mở khóa':'Khóa'}</button></td></tr>`); }
  function listingForm(item) { const p=item||{}; return `<h1 class="h3">${item?'Sửa tin đăng':'Đăng tin mới'}</h1><form data-form="listing" class="card card-body row g-3"><input type="hidden" name="id" value="${esc(p.id||'')}"><div class="col-md-8"><label class="form-label">Tên tin</label><input class="form-control" name="name" value="${esc(p.name||'')}" required></div><div class="col-md-4"><label class="form-label">Loại BĐS</label><select class="form-select" name="type">${rows('categories').filter((c)=>c.active).map((c)=>`<option ${p.type===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="col-md-4"><label class="form-label">Giá (triệu/tháng)</label><input class="form-control" name="price" type="number" min="0.1" step="0.1" value="${p.price||''}" required></div><div class="col-md-4"><label class="form-label">Diện tích (m²)</label><input class="form-control" name="area" type="number" min="1" value="${p.area||''}" required></div><div class="col-md-4"><label class="form-label">Quận</label><input class="form-control" name="district" value="${esc(p.district||'')}" required></div><div class="col-md-4"><label class="form-label">Phòng ngủ</label><input class="form-control" name="bedrooms" type="number" value="${p.bedrooms||1}"></div><div class="col-md-4"><label class="form-label">Cách trường (m)</label><input class="form-control" name="schoolDistance" type="number" value="${p.schoolDistance||''}"></div><div class="col-md-4"><label class="form-label">Mức yên tĩnh</label><select class="form-select" name="quietness">${['Thấp','Trung bình','Cao','Rất cao'].map((x)=>`<option ${p.quietness===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="col-md-4"><label class="form-label">Chỗ làm việc</label><select class="form-select" name="workspace"><option value="false">Không</option><option value="true" ${p.workspace?'selected':''}>Có</option></select></div><div class="col-12"><label class="form-label">Mô tả</label><textarea class="form-control" name="description">${esc(p.description||'')}</textarea></div><div class="col-12"><button class="btn btn-primary">${item?'Lưu thay đổi':'Gửi duyệt'}</button></div></form>`; }
  function dashboard(kind) { const listings=rows('properties'), leads=rows('leads'), views=rows('viewings'); const kpis=kind==='agent'?[['Tin đang hoạt động',listings.filter((p)=>p.status==='Đã duyệt').length],['Chờ duyệt',listings.filter((p)=>p.status==='Chờ duyệt').length],['Lead mới',leads.filter((l)=>l.status==='Mới').length],['Lịch sắp tới',views.filter((v)=>new Date(v.scheduledAt)>new Date()&&v.status!=='Đã hủy').length]]:[['Người dùng',rows('users').length],['Tin đăng',listings.length],['Lead',leads.length],['Báo cáo',rows('reports').length]]; return `<h1 class="h3">${kind==='agent'?'Tổng quan môi giới':'Tổng quan nền tảng'}</h1><div class="row g-3 mb-4">${kpis.map(([name,count])=>`<div class="col-6 col-xl-3"><div class="card"><div class="card-body"><div class="text-secondary">${name}</div><div class="display-6 fw-bold">${count}</div></div></div></div>`).join('')}</div>${kind==='agent'?`<div class="d-flex gap-2"><a class="btn btn-primary" href="${HomeFitAuth.pageUrl('agent-listing-upload.html')}">Đăng tin</a><a class="btn btn-outline-primary" href="${HomeFitAuth.pageUrl('agent-lead-management.html')}">Xem lead</a><a class="btn btn-outline-primary" href="${HomeFitAuth.pageUrl('agent-viewing-schedule.html')}">Lịch xem</a></div>`:`<h2 class="h5">Thống kê AI</h2><p>Sự kiện AI ghi nhận: ${rows('aiEvents').length}</p>`}`; }
  function reviewQueue(list) { const queue=list.filter((p)=>p.status==='Chờ duyệt').concat(rows('reports').filter((r)=>r.status!=='Hoàn thành').map((r)=>prop(r.propertyId)).filter(Boolean)); return `<h1 class="h3">Hàng chờ kiểm duyệt <span class="badge text-bg-warning">${queue.length}</span></h1>${dataTable(['Tin','Môi giới','Trạng thái','Quyết định'],queue,(p)=>`<tr><td>${esc(p.name)}</td><td>Trần Thị B</td><td>${esc(p.status)}</td><td><button class="btn btn-sm btn-success" data-action="approve" data-id="${p.id}">Duyệt</button> <button class="btn btn-sm btn-outline-danger" data-action="reject" data-id="${p.id}">Từ chối</button> <button class="btn btn-sm btn-outline-warning" data-action="request-more" data-id="${p.id}">Yêu cầu bổ sung</button></td></tr>`)}<div class="card mt-3"><div class="card-body"><h2 class="h5">Listing Summary · AI</h2><p>AI tóm tắt thông tin tin đăng để hỗ trợ quyết định. Kiểm duyệt viên vẫn là người quyết định.</p><div class="d-flex gap-2 flex-wrap">${['Chấp nhận','Sửa','Từ chối','Tạo lại','Lưu'].map((x)=>`<button class="btn btn-sm btn-outline-primary" data-action="ai-action" data-value="${x}">${x}</button>`).join('')}</div></div></div>`; }
  function dataQuality(list) { const issues=list.filter((p)=>!p.image||p.price>20||p.area<30); return `<h1 class="h3">Chất lượng dữ liệu</h1><div class="alert alert-warning">${issues.length} tin cần kiểm tra</div><button class="btn btn-primary mb-3" data-action="scan-quality">Chạy kiểm tra</button>${dataTable(['Tin','Vấn đề','Giá'],issues,(p)=>`<tr><td>${esc(p.name)}</td><td>${!p.image?'Thiếu ảnh':p.price>20?'Giá bất thường':'Diện tích nhỏ'}</td><td>${money(p.price)}</td></tr>`)}`; }
  function categoriesPage() { return `<h1 class="h3">Danh mục hệ thống</h1><ul class="nav nav-tabs"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#categories">Loại BĐS</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#labels">Nhãn nhu cầu</button></li></ul><div class="tab-content p-3"><div class="tab-pane fade show active" id="categories"><button class="btn btn-primary mb-3" data-action="new-category">Thêm loại BĐS</button>${dataTable(['Tên loại','Tin đang khớp','Trạng thái'],rows('categories'),(c)=>`<tr><td>${esc(c.name)}</td><td>${rows('properties').filter((p)=>p.type===c.name).length}</td><td>${c.active?'Đang dùng':'Đã tắt'}</td></tr>`)}</div><div class="tab-pane fade" id="labels">${dataTable(['Nhãn','Quy tắc','Tin khớp','Trạng thái'],rows('needLabels'),(label)=>`<tr><td>${esc(label.name)}</td><td>${esc(label.rule)}</td><td>${rows('properties').filter((p)=>label.id==='nearSchool'?p.schoolDistance<=500:label.id==='quiet'?['Cao','Rất cao'].includes(p.quietness):label.id==='workspace'?p.workspace:p.bedrooms>=2&&['Cao','Rất cao'].includes(p.quietness)).length}</td><td>${label.active?'Đang dùng':'Đã tắt'}</td></tr>`)}</div></div>`; }

  function profilePage(user) {
    const account=rows('users').find((item)=>item.id===user.id)||{};
    return `<h1 class="h3">Hồ sơ cá nhân</h1><ul class="nav nav-tabs"><li class="nav-item"><button class="nav-link active" data-bs-toggle="tab" data-bs-target="#profile-info">Thông tin cá nhân</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#profile-security">Bảo mật</button></li><li class="nav-item"><button class="nav-link" data-bs-toggle="tab" data-bs-target="#profile-preferences">Thông báo</button></li></ul><div class="tab-content p-3 bg-white border border-top-0 rounded-bottom"><div class="tab-pane fade show active" id="profile-info"><form data-form="profile" class="row g-3"><div class="col-md-6"><label class="form-label">Họ tên</label><input class="form-control" name="name" value="${esc(account.name)}" required></div><div class="col-md-6"><label class="form-label">Email</label><input class="form-control" value="${esc(account.email)}" disabled></div><div class="col-md-6"><label class="form-label">Số điện thoại</label><input class="form-control" name="phone" value="${esc(account.phone||'')}" pattern="[0-9]{10}"></div><div class="col-12"><button class="btn btn-primary">Lưu thông tin</button></div></form></div><div class="tab-pane fade" id="profile-security"><form data-form="password" class="row g-3"><div class="col-md-6"><label class="form-label">Mật khẩu hiện tại</label><input class="form-control" name="currentPassword" type="password" required></div><div class="col-md-6"><label class="form-label">Mật khẩu mới</label><input class="form-control" name="newPassword" type="password" minlength="6" required></div><div class="col-md-6"><label class="form-label">Nhập lại mật khẩu mới</label><input class="form-control" name="confirmPassword" type="password" minlength="6" required></div><div class="col-12"><button class="btn btn-primary">Đổi mật khẩu</button></div></form></div><div class="tab-pane fade" id="profile-preferences"><p>Chọn các cập nhật bạn muốn nhận qua thông báo.</p><div class="form-check"><input class="form-check-input" type="checkbox" checked><label class="form-check-label">Lịch xem và tin nhắn</label></div><div class="form-check"><input class="form-check-input" type="checkbox" checked><label class="form-check-label">Gợi ý nhà phù hợp</label></div><button class="btn btn-primary mt-3" data-action="save-preferences">Lưu lựa chọn</button></div></div>`;
  }

  function notificationsPage(user) {
    const list=rows('notifications').filter((item)=>item.userId===user.id);
    const cards=list.map((item)=>`<article class="card mb-2 notification-item" data-read="${item.read}"><div class="card-body"><b>${item.read?'':'● '}${esc(item.title)}</b><p class="mb-1">${esc(item.message)}</p><small class="text-secondary">${formatDate(item.createdAt,true)}</small></div></article>`).join('');
    return `<div class="d-flex justify-content-between align-items-center"><h1 class="h3">Thông báo</h1><button class="btn btn-outline-primary" data-action="read-all">Đánh dấu tất cả đã đọc</button></div><ul class="nav nav-pills my-3"><li class="nav-item"><button class="nav-link active" data-action="notification-filter" data-filter="all">Tất cả ${list.length}</button></li><li class="nav-item"><button class="nav-link" data-action="notification-filter" data-filter="unread">Chưa đọc ${list.filter((n)=>!n.read).length}</button></li><li class="nav-item"><button class="nav-link" data-action="notification-filter" data-filter="read">Đã đọc ${list.filter((n)=>n.read).length}</button></li></ul><div data-notification-list>${cards||'<div class="alert alert-light border">Bạn chưa có thông báo. Những cập nhật mới sẽ xuất hiện tại đây.</div>'}</div>`;
  }

  function initPage(page) {
    HomeFitStorage.ensureDatabase();
    if (protectedPages[page] && !HomeFitAuth.requireRole([protectedPages[page]])) return;
    if (['profile','notifications'].includes(page) && !HomeFitAuth.getCurrentUser()) { go('login'); return; }
    if(page==='agent-listing-edit'){
      const user=HomeFitAuth.getCurrentUser();const item=prop(new URLSearchParams(location.search).get('id'));
      if(!item||item.agentId!==user.id){go('403');return;}
    }
    const app = $('#app'); if (!app) return;
    const user = HomeFitAuth.getCurrentUser(); const internal = ['agent','moderator','admin'].includes(user?.role);
    const shell = document.createElement('div'); shell.innerHTML = '<div data-navbar></div><div class="container-fluid"><div class="row"><div class="col-md-3 col-lg-2 p-0" data-sidebar></div><main class="col p-3 p-lg-4"><div class="container-fluid px-0"><div data-page-content></div></div></main></div></div><div data-site-footer></div>';
    app.replaceChildren(...shell.childNodes); renderNavbar($('[data-navbar]', app));
    renderFooter($('[data-site-footer]', app));
    if (internal && menuByRole[user.role]) $('[data-sidebar]', app).innerHTML = renderSidebar(user, page);
    else $('[data-sidebar]', app).classList.add('d-none','d-md-block');
    const content = $('[data-page-content]', app);
    showState(content, 'loading'); window.setTimeout(() => {
      content.innerHTML = pageBody(page);
      if(page==='seeker-home-brief') $('[data-brief-result]',content).insertAdjacentHTML('afterend','<section class="card mt-3"><div class="card-body"><h2 class="h5">Lifestyle Matcher · AI-1</h2><p>Chấp nhận sẽ lưu brief và gửi lead cho môi giới nếu bạn đã bật chia sẻ.</p><div class="d-flex flex-wrap gap-2">'+aiButtons('AI-1')+'</div></div></section>');
    }, 500);
    document.addEventListener('click', handleClick);
    document.addEventListener('submit', handleSubmit);
    document.addEventListener('input', (event) => { if (event.target.matches('[data-form="search"] input')) applySearch(event.target.form); });
  }

  function handleClick(event) {
    const button=event.target.closest('[data-action]'); if(!button)return;
    const action=button.dataset.action; const id=button.dataset.id;
    if(action==='logout')HomeFitAuth.logout();
    if(action==='save-property'){const user=HomeFitAuth.getCurrentUser();if(!user){go('login');return;}const found=rows('savedProperties').some((s)=>s.userId===user.id&&s.propertyId===id);if(!found)HomeFitStorage.add('savedProperties',{userId:user.id,propertyId:id,note:''});toast(found?'Nhà đã có trong danh sách lưu.':'Đã lưu tin nhà.');}
    if(action==='add-compare'||action==='add-compare-selected'){const selected=JSON.parse(sessionStorage.getItem('hfCompare')||'["P01","P02"]');const value=action==='add-compare'?id:$('[data-select="compare"]')?.value;if(!selected.includes(value)&&selected.length<3)selected.push(value);sessionStorage.setItem('hfCompare',JSON.stringify(selected));$('#compare-results').innerHTML=compareTable(selected);toast('Đã cập nhật danh sách so sánh.');}
    if(action==='remove-compare'){const selected=JSON.parse(sessionStorage.getItem('hfCompare')||'["P01","P02","P03"]').filter((x)=>x!==id);sessionStorage.setItem('hfCompare',JSON.stringify(selected));$('#compare-results').innerHTML=compareTable(selected);}
    if(action==='rank-compare'){const ids=JSON.parse(sessionStorage.getItem('hfCompare')||'["P01","P02","P03"]');const result=HomeFitAI.compareProperties(ids.map(prop).filter(Boolean));$('[data-ranking]').innerHTML=`<div class="alert alert-success">${result.rankings.map((r)=>`${esc(prop(r.propertyId).name)}: ${r.score}/100`).join(' · ')}</div>`;HomeFitAI.recordEvent('AI-3',result.status==='result'?'result':'uncertain');}
    if(action==='remove-brief'){button.closest('.alert')?.remove();toast('Đã bỏ chip Brief khỏi kết quả hiện tại.','info');}
    if(action==='compare-selected')go('seeker-property-compare');
    if(action==='notification-filter'){
      const filter=button.dataset.filter;document.querySelectorAll('.notification-item').forEach((item)=>{item.hidden=filter==='unread'?item.dataset.read==='true':filter==='read'?item.dataset.read==='false':false;});
      button.closest('.nav')?.querySelectorAll('.nav-link').forEach((tab)=>tab.classList.remove('active'));button.classList.add('active');
    }
    if(action==='save-preferences')toast('Đã lưu lựa chọn thông báo.');
    if(action==='read-all'){const user=HomeFitAuth.getCurrentUser();rows('notifications').filter((n)=>n.userId===user.id).forEach((n)=>HomeFitStorage.update('notifications',n.id,{read:true}));toast('Đã đánh dấu thông báo đã đọc.');location.reload();}
    if(action==='archive-property')confirmDialog('Bạn muốn lưu trữ tin này?').then((yes)=>{if(yes){HomeFitStorage.update('properties',id,{status:'Lưu trữ'});location.reload();}});
    if(action==='approve'||action==='reject'||action==='request-more'){const status=action==='approve'?'Đã duyệt':action==='reject'?'Từ chối':'Cần bổ sung';HomeFitStorage.update('properties',id,{status});HomeFitAI.recordEvent('AI-2 moderator',status);toast(`Tin đã chuyển trạng thái: ${status}`);location.reload();}
    if(action==='toggle-user'){const item=HomeFitStorage.getById('users',id);if(id===HomeFitAuth.getCurrentUser()?.id){toast('Bạn không thể tự khóa tài khoản của mình.','warning');return;}confirmDialog('Xác nhận thay đổi trạng thái tài khoản?').then((yes)=>{if(yes){HomeFitStorage.update('users',id,{status:item.status==='Khóa'?'Hoạt động':'Khóa'});location.reload();}});}
    if(action==='open-lead'){const lead=HomeFitStorage.getById('leads',id);$('[data-lead-detail]').innerHTML=`<h3 class="h5">${esc(lead.name)}</h3><p>${esc(lead.phone)} · ${esc(lead.source)}</p><p>${esc(lead.notes)}</p><p>Điểm AI: ${lead.score} · ${esc(lead.status)}</p><button class="btn btn-primary" data-action="book-viewing" data-id="${esc(lead.propertyId)}">Đặt lịch xem</button>`;bootstrap.Offcanvas.getOrCreateInstance($('#leadDrawer')).show();}
    if(action==='book-viewing'||action==='report-property'||action==='send-message'||action==='new-lead'||action==='new-report'||action==='new-user'||action==='new-category')openQuickModal(action,id);
    if(action==='ai-action'){
      const aiName=button.dataset.aiName||'AI-2'; const choice=button.dataset.value;
      if(HomeFitAI.simulateError()){HomeFitAI.recordEvent(aiName,'error');toast('Chưa thể tạo gợi ý lúc này. Vui lòng thử lại.','danger');return;}
      if(aiName==='AI-2 seeker'&&choice==='Chấp nhận'){
        const propertyId=new URLSearchParams(location.search).get('id')||'P01';const user=HomeFitAuth.getCurrentUser();
        const saved=rows('savedProperties').find((item)=>item.userId===user.id&&item.propertyId===propertyId);
        if(saved)HomeFitStorage.update('savedProperties',saved.id,{note:HomeFitAI.listingSummary(prop(propertyId)).summary});
        else HomeFitStorage.add('savedProperties',{userId:user.id,propertyId,note:HomeFitAI.listingSummary(prop(propertyId)).summary});
      }
      if(aiName==='AI-1'&&choice==='Chấp nhận'){
        const user=HomeFitAuth.getCurrentUser();const ownerBriefs=rows('briefs').filter((item)=>item.ownerId===user.id);const brief=ownerBriefs[ownerBriefs.length-1];
        if(brief?.shareWithAgent&&!rows('leads').some((lead)=>lead.briefId===brief.id))HomeFitStorage.add('leads',{name:user.name,phone:rows('users').find((item)=>item.id===user.id)?.phone||'',source:'Home Brief',score:HomeFitAI.matchScore(brief,prop('P01')),propertyId:'P01',briefId:brief.id,status:'Mới',agentId:'user_b1',notes:brief.description});
      }
      HomeFitAI.recordEvent(aiName,choice==='Chấp nhận'?'accepted':choice==='Từ chối'?'rejected':choice==='Tạo lại'?'regenerated':choice==='Lưu'?'saved':'edited');
      const meaning=aiName==='AI-2 seeker'&&choice==='Chấp nhận'?'Đã ghim tóm tắt vào ghi chú nhà đã lưu.':aiName==='AI-3'&&choice==='Chấp nhận'?'Đã lưu kết quả xếp hạng.':`Đã ghi nhận: ${choice}.`;
      toast(meaning);
    }
    if(action==='scan-quality'){toast('Đã quét danh sách tin theo quy tắc chất lượng.');}
  }

  function openQuickModal(action,id) {
    const title=action==='book-viewing'?'Đặt lịch xem nhà':action==='report-property'||action==='new-report'?'Tạo báo cáo tin':action==='new-lead'?'Thêm khách hàng':action==='new-user'?'Thêm tài khoản':'Thêm danh mục';
    const fields=action==='book-viewing'?`<label class="form-label">Ngày</label><input class="form-control mb-3" type="date" name="date" required><label class="form-label">Giờ</label><input class="form-control mb-3" type="time" name="time" min="08:00" max="20:00" required><label class="form-label">Lời nhắn</label><textarea class="form-control" name="note"></textarea>`:action==='send-message'?`<label class="form-label">Họ tên</label><input class="form-control mb-3" name="name" required><label class="form-label">Số điện thoại</label><input class="form-control mb-3" name="phone" pattern="[0-9]{10}" required><label class="form-label">Nội dung</label><textarea class="form-control" name="notes" minlength="10" required></textarea>`:action==='report-property'||action==='new-report'?`<label class="form-label">Lý do</label><select class="form-select mb-3" name="reason"><option>Sai thông tin giá</option><option>Ảnh không đúng thực tế</option><option>Nghi trùng lặp</option></select><label class="form-label">Mô tả</label><textarea class="form-control" name="note" minlength="10" required></textarea>`:action==='new-lead'?`<label class="form-label">Họ tên</label><input class="form-control mb-3" name="name" required><label class="form-label">Số điện thoại</label><input class="form-control mb-3" name="phone" pattern="[0-9]{10}" required><label class="form-label">Nhu cầu</label><textarea class="form-control" name="notes" required></textarea>`:action==='new-user'?`<label class="form-label">Họ tên</label><input class="form-control mb-3" name="name" required><label class="form-label">Email</label><input class="form-control" type="email" name="email" required>`:`<label class="form-label">Tên</label><input class="form-control" name="name" required>`;
    const root=document.createElement('div');root.className='modal fade';root.innerHTML=`<div class="modal-dialog"><form class="modal-content" data-form="quick-action" data-action-name="${action}" data-id="${esc(id||'')}"><div class="modal-header"><h2 class="modal-title fs-5">${title}</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body">${fields}</div><div class="modal-footer"><button class="btn btn-primary">Lưu</button></div></form></div>`;document.body.append(root);const modal=new bootstrap.Modal(root);root.addEventListener('hidden.bs.modal',()=>root.remove(),{once:true});modal.show();
  }

  function handleSubmit(event) {
    const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();const fd=new FormData(form);const data=Object.fromEntries(fd.entries());const type=form.dataset.form;
    if(type==='quick-search'){go('seeker-property-search',`?q=${encodeURIComponent(data.q||'')}`);}
    if(type==='login'){const result=HomeFitAuth.login(data.email,data.password);if(!result.ok){$('[data-error]',form).textContent=result.message;return;}go(result.user.role==='seeker'?'seeker-property-search':result.user.role==='agent'?'agent-dashboard':result.user.role==='moderator'?'moderator-listing-review':'admin-platform-dashboard');}
    if(type==='register'){if(data.password!==data.confirm){toast('Mật khẩu nhập lại chưa khớp.','danger');return;}if(rows('users').some((u)=>u.email.toLowerCase()===data.email.toLowerCase())){toast('Email đã được sử dụng.','danger');return;}HomeFitStorage.add('users',{name:data.name,email:data.email,password:data.password,role:'seeker',status:'Hoạt động'});toast('Tạo tài khoản thành công.');go('login');}
    if(type==='forgot'){const user=rows('users').find((u)=>u.email===data.email);if(!form.dataset.step){if(!user){toast('Không tìm thấy email này.','danger');return;}form.querySelector('button').disabled=true;setTimeout(()=>{form.dataset.step='reset';form.querySelector('button').disabled=false;$('[data-reset-fields]',form).hidden=false;toast('Nếu địa chỉ tồn tại, hướng dẫn đặt lại sẽ được gửi tới email.');},500);return;}if(data.password.length<6||data.password!==data.confirm){toast('Mật khẩu chưa hợp lệ hoặc chưa khớp.','danger');return;}HomeFitStorage.update('users',user.id,{password:data.password});toast('Đã đổi mật khẩu.');go('login');}
    if(type==='search'){applySearch(form);}
    if(type==='brief'){const brief=HomeFitStorage.add('briefs',{...data,id:undefined,ownerId:HomeFitAuth.getCurrentUser()?.id,name:`Brief #${rows('briefs').length+1}`,budget:Number(data.budget),bedrooms:Number(data.bedrooms),shareWithAgent:fd.has('shareWithAgent'),status:'Đang dùng',priorities:{nearSchool:'Bắt buộc',quiet:'Bắt buộc',workspace:'Nên có',family:'Nên có'},keywords:(data.description.match(/gần trường|yên tĩnh|gia đình/gi)||[])});const matches=rows('properties').filter((p)=>p.status==='Đã duyệt').map((p)=>({p,score:HomeFitAI.matchScore(brief,p)})).sort((a,b)=>b.score-a.score);$('[data-brief-result]').innerHTML=`<div class="alert alert-success">AI đã phân tích nhu cầu. Có ${matches.length} tin đã duyệt để xem. <a href="${HomeFitAuth.pageUrl('seeker-property-search.html')}">Xem nhà phù hợp</a></div>`;HomeFitAI.recordEvent('AI-1','result');}
    if(type==='profile'){const user=HomeFitAuth.getCurrentUser();HomeFitStorage.update('users',user.id,{name:data.name,phone:data.phone});HomeFitAuth.setCurrentUser({...user,name:data.name});toast('Đã cập nhật hồ sơ.');}
    if(type==='password'){const user=HomeFitAuth.getCurrentUser();const account=HomeFitStorage.getById('users',user.id);if(data.currentPassword!==account.password){toast('Mật khẩu hiện tại chưa đúng.','danger');return;}if(data.newPassword.length<6||data.newPassword!==data.confirmPassword){toast('Mật khẩu mới chưa hợp lệ hoặc chưa khớp.','danger');return;}HomeFitStorage.update('users',user.id,{password:data.newPassword});toast('Mật khẩu đã được cập nhật.');form.reset();}
    if(type==='help-ai'){const answer=/lịch|xem nhà/i.test(data.question)?'Mở chi tiết tin và chọn Đặt lịch xem nhà.':/so sánh/i.test(data.question)?'Chọn các tin rồi mở trang So sánh.':/báo cáo/i.test(data.question)?'Mở chi tiết tin và chọn Báo cáo tin.':'Mình chỉ trả lời về cách dùng HomeFit.';$('[data-help-answer]').innerHTML=`<div class="alert alert-info">${answer}</div>`;}
    if(type==='listing'){const id=data.id;const values={name:data.name,type:data.type,price:Number(data.price),area:Number(data.area),district:data.district,bedrooms:Number(data.bedrooms),schoolDistance:Number(data.schoolDistance),quietness:data.quietness,workspace:data.workspace==='true',description:data.description,agentId:HomeFitAuth.getCurrentUser()?.id,status:'Chờ duyệt'};if(id){HomeFitStorage.update('properties',id,values);toast('Đã cập nhật tin.');}else{HomeFitStorage.add('properties',values);toast('Tin đã được gửi để kiểm duyệt.');}go('agent-listing-management');}
    if(type==='viewing'||type==='quick-action'){const action=type==='viewing'?'viewing':form.dataset.actionName;const id=form.dataset.id;const user=HomeFitAuth.getCurrentUser();if(action==='viewing'||action==='book-viewing'){const propertyId=id||data.propertyId||rows('properties')[0].id;const date=new Date(`${data.date}T${data.time}`);if(Number.isNaN(date.getTime())||date<new Date()||!data.time||data.time<'08:00'||data.time>'20:00'){toast('Kiểm tra lại ngày và giờ (08:00–20:00).','danger');return;}const duplicate=rows('viewings').some((v)=>v.propertyId===propertyId&&new Date(v.scheduledAt).getTime()===date.getTime()&&v.status!=='Đã hủy');if(duplicate){toast('Nhà đã có lịch xem vào khung giờ này.','danger');return;}HomeFitStorage.add('viewings',{customerId:user?.role==='seeker'?user.id:'',customerName:user?.name||data.name,leadId:data.leadId||'',propertyId,scheduledAt:date.toISOString(),status:'Chờ xác nhận',note:data.note||''});toast('Đã tạo lịch xem.');}if(action==='report-property'||action==='new-report'){HomeFitStorage.add('reports',{propertyId:id||'P01',reason:data.reason,reporterId:user?.id||'user_a1',status:'Mới',note:data.note,conclusion:''});toast('Đã gửi báo cáo.');}if(action==='send-message'){HomeFitStorage.add('leads',{name:data.name,phone:data.phone,notes:data.notes,source:'Chi tiết tin',score:0,propertyId:id,status:'Mới',agentId:prop(id)?.agentId||'user_b1'});toast('Đã gửi tin nhắn và tạo lead cho môi giới.');}if(action==='new-lead'){HomeFitStorage.add('leads',{...data,source:'Nhập tay',score:0,propertyId:'P01',status:'Mới',agentId:user?.id});toast('Đã thêm khách hàng.');}if(action==='new-user'){HomeFitStorage.add('users',{...data,password:'123456',role:'seeker',status:'Hoạt động'});toast('Đã thêm tài khoản.');}if(action==='new-category'){HomeFitStorage.add('categories',{...data,active:true});toast('Đã thêm danh mục.');}bootstrap.Modal.getInstance(form.closest('.modal'))?.hide();setTimeout(()=>location.reload(),400);}
  }

  function applySearch(form) {
    const data=new FormData(form);const q=(data.get('q')||'').toLowerCase();const district=data.get('district');const budgetText=q.match(/(?:dưới|tối đa|≤)\s*(\d+(?:[,.]\d+)?)/);const budget=Number(data.get('budget')||budgetText?.[1]?.replace(',','.')||1000);
    const ignored=['gần','trường','đại','học','yên','tĩnh','dưới','tối','đa','triệu','ở','và','có','chỗ','làm','việc'];const cleanQuery=q.replace(/(?:dưới|tối đa|≤)\s*\d+(?:[,.]\d+)?\s*triệu/g,' ').replace(/[,.]/g,' ');const terms=cleanQuery.split(/\s+/).filter((term)=>term&&!ignored.includes(term));
    const filtered=rows('properties').filter((p)=>{const haystack=`${p.name} ${p.district} ${p.description}`.toLowerCase();const textMatches=terms.length===0||terms.some((term)=>haystack.includes(term));const nearMatches=!/gần trường|gần đại học/.test(q)||p.schoolDistance<=500;const quietMatches=!/yên tĩnh/.test(q)||['Cao','Rất cao'].includes(p.quietness);return p.status==='Đã duyệt'&&p.price<=budget&&(!district||p.district===district)&&textMatches&&nearMatches&&quietMatches;});
    const host=$('#property-results');if(host)host.innerHTML=propertyGrid(filtered,true);
  }

  window.HomeFitUI = { renderNavbar, renderSidebar, toast, confirmDialog, showState, formatDate, tagLines, initPage, propertyGrid, pageTitles };
})();







